export function renderArenaPage() {
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="Arena audits whether WebMCP tools preserve human protections and delegated authority.">
<title>Arena — The proving ground for the agentic web</title><link rel="stylesheet" href="/arena.css"></head>
<body>
<header class="topbar"><a class="brand" href="/"><span class="brand-mark">A</span><span>Arena</span></a><nav class="status-strip"><span id="webmcp-status" class="status waiting">Checking WebMCP</span><span id="proof-status" class="status">Proof key</span><span id="runtime-status" class="status">Runtime</span></nav></header>
<main>
<section class="hero"><div><p class="eyebrow">The crash-test lab for the agentic web</p><h1>A tool description<br>is <em>not proof.</em></h1></div><p class="hero-copy">This workbench rehearses authored attack fixtures. Arena’s target runner separately records human and agent routes before it makes a measured claim.</p></section>
<section class="lab-shell" aria-labelledby="audit-title">
  <div class="lab-header"><div><p class="eyebrow">Synthetic threat lab</p><h2 id="audit-title">Human-vs-Agent Boundary Rehearsal</h2></div><div class="lab-controls"><label>Incident<select id="scenario-select"></select></label><label>Version<select id="version-select"><option value="vulnerable">Vulnerable</option><option value="fixed">Fixed</option></select></label><label>Mode<select id="mode-select"><option value="observe">Observe</option><option value="warn">Warn</option><option value="challenge">Challenge</option><option value="enforce" selected>Enforce</option></select></label><button id="run-button" class="primary">Run Synthetic Fixture</button></div></div>
  <div class="route-comparison">
    <article class="route-card human-card"><div class="card-label"><span class="route-dot human"></span>Authored human route</div><h3 id="human-title">Reference workflow</h3><div id="human-effects" class="effect-list empty">Run a fixture to inspect the authored reference effects.</div></article>
    <aside class="policy-rail"><span class="rail-line"></span><div id="policy-orb" class="policy-orb idle">?</div><strong id="policy-status">Awaiting evidence</strong><span id="policy-detail">Observe → compare → decide</span><div id="policy-codes" class="policy-codes"></div></aside>
    <article class="route-card agent-card"><div class="card-label"><span class="route-dot agent"></span>Authored agent route</div><h3 id="agent-title">WebMCP fixture</h3><div id="agent-effects" class="effect-list empty">The authored WebMCP effects will appear here.</div></article>
  </div>
  <div class="counterfactual"><div><span>Raw agent</span><strong id="raw-outcome">No run yet</strong></div><b>versus</b><div><span>Arena governed</span><strong id="governed-outcome">No run yet</strong></div></div>
</section>
<section class="evidence-grid">
  <article class="panel findings-panel"><div class="panel-head"><div><p class="eyebrow">Evidence</p><h2>Protection divergences</h2></div><span id="finding-count" class="metric">0 findings</span></div><div id="findings" class="empty-state">Run the vulnerable gym incident to see a booking-window bypass and another member’s reservation cancellation.</div></article>
  <article class="panel proof-panel"><div class="panel-head"><div><p class="eyebrow">Arena Proof</p><h2>Signed fixture receipt</h2></div><span id="attestation-state" class="metric">Not issued</span></div><dl class="proof-facts"><div><dt>Algorithm</dt><dd id="proof-algorithm">—</dd></div><div><dt>Fixture run</dt><dd id="proof-audit">—</dd></div><div><dt>Authored trace</dt><dd id="proof-trace">—</dd></div><div><dt>Contract</dt><dd id="contract-status">Not reviewed</dd></div><div><dt>Previous proof</dt><dd id="proof-previous">—</dd></div></dl><div class="button-row"><button id="approve-contract-button" class="secondary" disabled>Review fixture contract</button><button id="verify-button" class="secondary" disabled>Verify signature</button><button id="fixed-button" class="primary" disabled>Rerun fixed</button></div></article>
</section>
<section class="panel guided-audit-panel" aria-labelledby="guided-audit-title" data-evidence-source="server-owned-checkout">
  <div class="panel-head"><div><p class="eyebrow">Owned target audit</p><h2 id="guided-audit-title">Human-vs-Agent Checkout Proof</h2></div><span id="guided-audit-state" class="metric">Not started</span></div>
  <p class="measured-intro">Start a measured checkout audit from a server-owned preset. Arena prepares the human baseline, binds the exact tool and arguments to a review, waits for a human decision, then watches delayed backend effects through a terminal settlement watermark.</p>
  <div class="guided-audit-grid">
    <article class="guided-step"><span class="step-number">01</span><h3>Start measured checkout audit</h3><p>An agent may start and poll. It cannot supply routes, evidence, or approval.</p><div class="button-row"><button id="checkout-vulnerable-button" class="primary">Test vulnerable preview</button><button id="checkout-fixed-button" class="secondary">Test fixed preview</button></div></article>
    <article class="guided-step"><span class="step-number">02</span><h3>Review exact contract</h3><dl id="guided-contract" class="proof-facts guided-contract"><div><dt>Target</dt><dd>Awaiting audit</dd></div><div><dt>Tool</dt><dd>—</dd></div><div><dt>Claim</dt><dd>—</dd></div><div><dt>Contract</dt><dd>—</dd></div></dl><button id="guided-approve-button" class="primary wide-button" disabled>Approve and run</button></article>
    <article class="guided-step"><span class="step-number">03</span><h3>Observe settled outcome</h3><div id="guided-result" class="inline-state">No route has executed.</div><div id="guided-history" class="audit-history"></div></article>
  </div>
</section>
<section class="panel measured-panel" aria-labelledby="measured-title" data-evidence-source="submitted-boundary-bundle">
  <div class="panel-head"><div><p class="eyebrow">Evidence bundle inspector</p><h2 id="measured-title">Measured Boundary Bundle Inspector</h2></div><div class="metric-stack"><span id="measured-verification-state" class="metric">Not inspected</span><span id="measured-authenticity-state" class="metric">Authenticity unknown</span></div></div>
  <p class="measured-intro">Paste an <code>arena.boundary_evidence_bundle</code> expected from a recorder-owned target audit. Arena verifies hashes and derived semantics, not origin. Producer authenticity is reported separately; an unsigned bundle is not authenticated. Authored synthetic fixture receipts are rejected.</p>
  <div class="bundle-import-grid">
    <div class="bundle-input"><label for="measured-bundle-input">Boundary bundle JSON</label><textarea id="measured-bundle-input" rows="10" spellcheck="false" placeholder='{"kind":"arena.boundary_evidence_bundle", ...}'></textarea><button id="measured-verify-button" class="primary">Verify and inspect bundle</button></div>
    <div><h3>Reviewed contract</h3><dl id="measured-contract-summary" class="proof-facts measured-contract"><div><dt>Tool</dt><dd>Awaiting bundle</dd></div><div><dt>Contract</dt><dd>—</dd></div><div><dt>Effects</dt><dd>—</dd></div><div><dt>Baseline</dt><dd>—</dd></div></dl><h3 class="subhead">Capture gaps</h3><div id="measured-capture-gaps" class="empty-state compact-empty">No bundle inspected.</div></div>
  </div>
  <div id="measured-layer-summary" class="measured-layers"><article><div class="layer-title"><h3>Route parity</h3><span id="measured-route-parity-state" class="metric">Not inspected</span></div><p>Did the agent route preserve the reviewed human route outcomes?</p><div id="measured-route-parity-findings" class="layer-findings">No inspected result.</div></article><article><div class="layer-title"><h3>Baseline safety</h3><span id="measured-baseline-safety-state" class="metric">Not inspected</span></div><p>Was the reviewed human baseline itself safe under the declared invariants?</p><div id="measured-baseline-safety-findings" class="layer-findings">No inspected result.</div></article></div>
  <div class="measured-result-head"><div><p class="eyebrow">Synchronized bundle evidence</p><h3>Human and agent timeline</h3></div><div id="measured-summary" class="metric">No verified verdict</div></div>
  <div class="measured-timeline"><article><div class="card-label"><span class="route-dot human"></span>Bundle human route</div><div id="measured-human-timeline" class="timeline-list empty">Inspected events will appear here.</div></article><article><div class="card-label"><span class="route-dot agent"></span>Bundle agent route</div><div id="measured-agent-timeline" class="timeline-list empty">Inspected events will appear here.</div></article></div>
  <div class="measured-difference-head"><h3>Finding and value differences</h3><span id="measured-finding-count" class="metric">0 findings</span></div><div id="measured-differences" class="empty-state">Inspect a measured bundle to compare route outcomes.</div>
</section>
<section class="panel corpus-panel"><div class="panel-head"><div><p class="eyebrow">Threat lab</p><h2>Synthetic incident corpus</h2></div><span id="corpus-count" class="metric">Loading</span></div><div id="scenario-grid" class="scenario-grid"></div></section>
<section class="operations-grid">
  <article class="panel"><div class="panel-head"><div><p class="eyebrow">Arena Guard</p><h2>Delegated authority</h2></div><span class="metric">Deterministic</span></div><form id="passport-form" class="compact-form"><label>Principal<input name="principalId" value="human_vasu" required></label><label>Agent<input name="agentId" value="browser_agent" required></label><label>Spend limit<input name="maxAmount" type="number" value="15000" min="0"></label><label>Minutes<input name="minutes" type="number" value="30" min="1"></label><input name="humanAuthorizationToken" type="password" placeholder="Operator token in production" aria-label="Operator token"><button class="primary" type="submit">Issue delegation</button></form><div id="passport-summary" class="inline-state">No active delegation.</div><button id="revoke-button" class="danger-link" disabled>Revoke active delegation</button></article>
  <article class="panel"><div class="panel-head"><div><p class="eyebrow">Arena CI</p><h2>Prevent regression</h2></div><span id="ci-state" class="metric">Awaiting audit</span></div><p class="muted">Export the same evidence to formats engineering and security teams already consume.</p><div class="format-grid"><button data-export="json" class="format-button">JSON<span>Evidence bundle</span></button><button data-export="sarif" class="format-button">SARIF<span>Code scanning</span></button><button data-export="junit" class="format-button">JUnit<span>CI test result</span></button></div></article>
  <article class="panel"><div class="panel-head"><div><p class="eyebrow">Agent drift</p><h2>Different agent, same boundary</h2></div><span class="metric">Provider-neutral</span></div><p class="muted">Import repeated runs to separate completion and refusal drift from Arena’s deterministic containment outcome.</p><button id="agent-profile-button" class="secondary wide-button">Run deterministic profile example</button><div id="agent-profile-result" class="inline-state">No profile comparison yet.</div></article>
</section>
</main><div id="toast" role="status" aria-live="polite"></div><script type="module" src="/arena.js"></script></body></html>`;
}

export const ARENA_SCRIPT = `
const app={scenarios:[],selectedScenario:null,currentRun:null,boundaryInspection:null,measuredAudit:null,passport:null,principalId:"human_vasu",agentId:"browser_agent",authorizationToken:"",toolController:null,ciArtifacts:null};
function tool(name,description,properties,execute,options){const settings=options||{};return{definition:{name,description,inputSchema:{type:"object",properties:properties||{},required:settings.required||[]},annotations:{readOnlyHint:settings.readOnly!==false,untrustedContentHint:settings.untrusted===true},async execute(input,{signal}={}){if(signal?.aborted)throw signal.reason;try{return await execute(input||{});}catch(error){return{error:error.message||String(error)};}}},options:{exposedTo:[location.origin]}};}
async function refreshWebMcpTools(){if(!document.modelContext?.registerTool){setStatus("webmcp-status","WebMCP unavailable","warn");return;}if(app.toolController)app.toolController.abort();app.toolController=new AbortController();const tools=[
tool("list_incident_scenarios","List Arena's executable vulnerable and repaired WebMCP security fixtures.",{},async()=>({scenarios:app.scenarios}),{readOnly:true}),
tool("select_incident_scenario","Select one incident fixture for a Human-vs-Agent Boundary Audit.",{scenarioId:{type:"string",description:"Scenario identifier."}},async input=>{selectScenario(input.scenarioId);return{selected:app.selectedScenario};},{readOnly:true,required:["scenarioId"]}),
tool("inspect_boundary_bundle","Check an Arena boundary evidence bundle for internal hash and semantic consistency, report producer authenticity separately, and update the bundle timeline.",{bundle:{type:"object",description:"A version 1 arena.boundary_evidence_bundle."}},async input=>inspectBoundaryBundle(input.bundle),{readOnly:true,required:["bundle"]}),
tool("start_measured_checkout_audit","Prepare a server-owned human-vs-agent Checkout audit and show the exact contract for human approval. This tool cannot approve or execute the agent route.",{version:{type:"string",enum:["vulnerable","fixed"],description:"Choose the intentionally vulnerable or repaired Checkout implementation."}},async input=>startMeasuredCheckoutAudit(input.version||"vulnerable"),{readOnly:false}),
tool("get_measured_audit_status","Poll a measured audit without changing or approving it.",{auditId:{type:"string",description:"Measured audit identifier returned by start_measured_checkout_audit."}},async input=>getMeasuredAuditStatus(input.auditId),{readOnly:true,required:["auditId"]})];
if(app.selectedScenario)tools.push(tool("run_synthetic_fixture","Replay the selected authored human and WebMCP fixture and issue a receipt explicitly scoped to synthetic evidence.",{version:{type:"string",enum:["vulnerable","fixed"]},mode:{type:"string",enum:["observe","warn","challenge","enforce"]}},async input=>runScenario(input.version,input.mode),{readOnly:false}),tool("compare_fixed_fixture","Replay the selected incident's authored repaired fixture and compare the verdict.",{},async()=>runScenario("fixed",document.querySelector("#mode-select").value),{readOnly:false}));
if(app.currentRun)tools.push(tool("explain_finding","Return root cause, evidence, risk, repair, and regression assertion for one finding.",{code:{type:"string"}},async input=>app.currentRun.report.findings.find(f=>f.code===input.code)||{error:"finding not found"},{readOnly:true,required:["code"]}),tool("verify_attestation","Verify the current Arena Proof signature.",{},verifyCurrentAttestation,{readOnly:true}),tool("export_ci_artifacts","Export the current audit as JSON, SARIF, and JUnit.",{},buildCurrentCiArtifacts,{readOnly:true}));
const results=await Promise.allSettled(tools.map(toolEntry=>document.modelContext.registerTool(toolEntry.definition,{...toolEntry.options,signal:app.toolController.signal})));setStatus("webmcp-status","WebMCP · "+results.filter(result=>result.status==="fulfilled").length+" tools","ok");}
async function loadScenarios(){const result=await getJson("/api/scenarios");app.scenarios=result.scenarios;const select=document.querySelector("#scenario-select");select.replaceChildren(...app.scenarios.map(scenario=>{const option=document.createElement("option");option.value=scenario.id;option.textContent=scenario.title;return option;}));document.querySelector("#corpus-count").textContent=app.scenarios.length+" paired fixtures";renderScenarioGrid();selectScenario("gym_waitlist");}
function selectScenario(id){const scenario=app.scenarios.find(candidate=>candidate.id===id);if(!scenario)throw new Error("Unknown scenario: "+id);app.selectedScenario=scenario;document.querySelector("#scenario-select").value=scenario.id;document.querySelectorAll(".scenario-card").forEach(card=>card.classList.toggle("selected",card.dataset.id===id));scheduleToolRefresh();}
async function runScenario(version,mode){if(!app.selectedScenario)throw new Error("Select an incident first");const selectedVersion=version||document.querySelector("#version-select").value;const selectedMode=mode||document.querySelector("#mode-select").value;document.querySelector("#version-select").value=selectedVersion;document.querySelector("#mode-select").value=selectedMode;setBusy(true);try{const result=await api("/api/scenarios/"+encodeURIComponent(app.selectedScenario.id)+"/run",{version:selectedVersion,mode:selectedMode});app.currentRun=result;app.ciArtifacts=null;renderRun(result);scheduleToolRefresh();toast(result.report.verdict==="pass"?"Fixture preserves the boundary":"Fixture demonstrates a divergence");return result;}finally{setBusy(false);}}
function renderRun(run){document.querySelector("#human-title").textContent=run.contract.tool_name+" · reference";document.querySelector("#agent-title").textContent=run.scenario.tool_name+" · "+run.version;renderEffects("human-effects",run.routes.human);renderEffects("agent-effects",run.routes.agent);const failed=run.report.verdict==="fail";const orb=document.querySelector("#policy-orb");orb.className="policy-orb "+(failed?"deny":"allow");orb.textContent=failed?"×":"✓";document.querySelector("#policy-status").textContent=run.enforcement.status.replaceAll("_"," ");document.querySelector("#policy-detail").textContent=run.mode+" mode · "+run.report.evidence_level.replaceAll("_"," ");document.querySelector("#policy-codes").replaceChildren(...run.report.findings.slice(0,4).map(f=>chip(f.code)));document.querySelector("#raw-outcome").textContent=run.counterfactual.raw.agent_outcome;document.querySelector("#governed-outcome").textContent=run.counterfactual.governed.agent_outcome;renderFindings(run.report.findings);renderProof(run.attestation,run.attestation_verified);document.querySelector("#fixed-button").disabled=run.version==="fixed";document.querySelector("#verify-button").disabled=false;document.querySelector("#approve-contract-button").disabled=run.contract.review_status==="approved";document.querySelector("#contract-status").textContent=run.contract.review_status;document.querySelector("#ci-state").textContent=failed?"Build blocked":"Ready to merge";}
function renderEffects(id,trace){const root=document.querySelector("#"+id);const effects=[];(trace.network||[]).forEach(request=>effects.push({kind:request.method,value:safePath(request.url)+(request.operation?" · "+request.operation:""),danger:["POST","PUT","PATCH","DELETE"].includes(request.method)}));Object.keys(trace.state?.after||{}).forEach(key=>{const before=trace.state.before[key],after=trace.state.after[key];if(JSON.stringify(before)!==JSON.stringify(after))effects.push({kind:"STATE",value:key+": "+display(before)+" → "+display(after),danger:true});});(trace.protections||[]).forEach(p=>effects.push({kind:"GUARD",value:p.replaceAll("_"," "),danger:false}));(trace.approvals||[]).forEach(a=>effects.push({kind:"HUMAN",value:a.kind+" · "+a.status,danger:false}));root.className="effect-list";root.replaceChildren(...effects.map(effect=>{const row=document.createElement("div");row.className="effect "+(effect.danger?"effect-danger":"");const kind=document.createElement("span");kind.textContent=effect.kind;const value=document.createElement("strong");value.textContent=effect.value;row.append(kind,value);return row;}));}
function renderFindings(findings){document.querySelector("#finding-count").textContent=findings.length+(findings.length===1?" finding":" findings");const root=document.querySelector("#findings");if(!findings.length){root.className="pass-state";root.textContent="No fixture divergence. The authored repaired route preserves the reviewed protections and effects.";return;}root.className="finding-list";root.replaceChildren(...findings.map(finding=>{const details=document.createElement("details");details.className="finding";details.open=finding.severity==="critical";const summary=document.createElement("summary");const severity=document.createElement("span");severity.className="severity "+finding.severity;severity.textContent=finding.severity;const title=document.createElement("strong");title.textContent=finding.title;const code=document.createElement("code");code.textContent=finding.code;summary.append(severity,title,code);const body=document.createElement("div");body.className="finding-body";body.append(fact("Evidence",finding.evidence||"Authored fixture divergence"),fact("Root cause",finding.root_cause),fact("Repair",finding.recommended_repair),fact("Regression",finding.regression_assertion));details.append(summary,body);return details;}));}
async function startMeasuredCheckoutAudit(version){if(!new Set(["vulnerable","fixed"]).has(version))throw new Error("Checkout version must be vulnerable or fixed");setMeasuredBusy(true);try{const nonce=globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random().toString(16).slice(2);const audit=await api("/api/measured-audits",{presetId:"checkout_"+version,idempotencyKey:"browser-"+nonce});app.measuredAudit=audit;renderMeasuredAudit(audit);toast("Contract ready for human review");return audit;}finally{setMeasuredBusy(false);}}
async function getMeasuredAuditStatus(auditId){if(typeof auditId!=="string"||!auditId)throw new Error("auditId is required");const audit=await getJson("/api/measured-audits/"+encodeURIComponent(auditId));app.measuredAudit=audit;renderMeasuredAudit(audit);return audit;}
async function approveMeasuredCheckoutAudit(){if(app.measuredAudit?.state!=="awaiting_approval")throw new Error("Start an audit before approving it");const button=document.querySelector("#guided-approve-button");button.disabled=true;button.textContent="Running and settling effects…";try{const audit=await api("/api/measured-audits/"+encodeURIComponent(app.measuredAudit.id)+"/approve",{humanId:app.principalId},app.authorizationToken);app.measuredAudit=audit;renderMeasuredAudit(audit);if(audit.result?.bundle)await inspectBoundaryBundle(audit.result.bundle);toast(audit.result?.verdict==="pass"?"Fixed route preserves the boundary":"Arena caught the hidden delayed charge");return audit;}finally{button.textContent="Approve and run";button.disabled=app.measuredAudit?.state!=="awaiting_approval";}}
function renderMeasuredAudit(audit){const state=document.querySelector("#guided-audit-state");state.textContent=audit.state.replaceAll("_"," ");state.className="metric "+(audit.state==="completed"?(audit.result?.verdict==="pass"?"verification-ok":"verification-fail"):audit.state==="awaiting_approval"?"verification-warn":"");const review=audit.review||{};document.querySelector("#guided-contract").replaceChildren(definitionRow("Target",review.targetPreset||"Awaiting audit"),definitionRow("Tool",review.toolName||"—"),definitionRow("Claim",review.claimScope||"—"),definitionRow("Contract",review.contractHash?review.contractHash.slice(0,18)+"…":"—"));document.querySelector("#guided-approve-button").disabled=audit.state!=="awaiting_approval";const result=document.querySelector("#guided-result");if(audit.result){const delayedCharges=audit.result.bundle?.events?.filter(event=>event.route==="agent"&&event.payload?.kind==="money").length||0;result.className=audit.result.verdict==="pass"?"pass-state":"inline-state guided-fail";result.textContent=audit.result.verdict==="pass"?"PASS · Human and agent previews preserve the same protection boundary.":audit.result.verdict==="inconclusive"?"INCONCLUSIVE · Effect settlement or authoritative evidence is incomplete.":"FAIL · "+delayedCharges+" hidden delayed charge detected after the tool returned.";}else{result.className="inline-state";result.textContent=audit.state==="awaiting_approval"?"Human review required. No agent route has executed.":audit.error?.code?.replaceAll("_"," ")||"Preparing server-owned evidence.";}document.querySelector("#guided-history").replaceChildren(...(audit.history||[]).map(entry=>{const node=document.createElement("span");node.textContent=entry.state.replaceAll("_"," ");return node;}));}
function setMeasuredBusy(value){for(const id of ["checkout-vulnerable-button","checkout-fixed-button"]){document.querySelector("#"+id).disabled=value;}}
function definitionRow(label,value){const row=document.createElement("div"),term=document.createElement("dt"),detail=document.createElement("dd");term.textContent=label;detail.textContent=value;row.append(term,detail);return row;}
async function inspectBoundaryBundle(bundle){if(!bundle||typeof bundle!=="object")throw new Error("A boundary evidence bundle is required");const inspection=await api("/api/boundary-bundles/inspect",{bundle});app.boundaryInspection=inspection;renderBoundaryInspection(inspection);toast(inspection.verification.semantic_valid?("Bundle semantics valid · "+inspection.authenticity.status.replaceAll("_"," ")):"Bundle verification failed");return inspection;}
async function inspectPastedBoundaryBundle(){const input=document.querySelector("#measured-bundle-input"),button=document.querySelector("#measured-verify-button");let bundle;try{bundle=JSON.parse(input.value);}catch{throw new Error("Paste valid boundary bundle JSON");}button.disabled=true;button.textContent="Verifying bundle…";try{const result=await inspectBoundaryBundle(bundle);input.value="";return result;}finally{button.disabled=false;button.textContent="Verify and inspect bundle";}}
function renderBoundaryInspection(inspection){const verification=inspection.verification||{},authenticity=inspection.authenticity||{},semanticValid=verification.semantic_valid===true;const state=document.querySelector("#measured-verification-state");state.textContent=semanticValid?"Semantics + hashes valid":"Rejected · "+(verification.reason||"invalid bundle");state.className="metric "+(semanticValid?"verification-ok":"verification-fail");const authenticityState=document.querySelector("#measured-authenticity-state");authenticityState.textContent=authenticity.authenticated?"Producer authenticated":authenticity.status==="unsigned"?"Unsigned producer":authenticity.status==="signer_untrusted"?"Signer not trusted":authenticity.status==="invalid_signature"?"Invalid signature":"Authenticity unverified";authenticityState.className="metric "+(authenticity.authenticated?"verification-ok":authenticity.status==="invalid_signature"?"verification-fail":"verification-warn");document.querySelector("#measured-summary").textContent=semanticValid?(inspection.summary.verdict+" · "+inspection.summary.assurance.tier.replaceAll("_"," ")):("Unverified · "+(verification.reason||"invalid bundle"));renderMeasuredContract(inspection.contract,semanticValid);renderMeasuredLayers(inspection.layers||{},semanticValid);renderMeasuredGaps(inspection.capture_gaps,semanticValid);renderMeasuredTimeline(inspection.timeline?.rows||[],semanticValid);renderMeasuredDifferences(inspection.differences||[],inspection.summary?.finding_codes||[],semanticValid);}
function renderMeasuredLayers(layers,verified){for(const entry of [["route-parity",layers.route_parity],["baseline-safety",layers.baseline_safety]]){const id=entry[0],layer=entry[1]||{status:"unverified",finding_codes:[]};const state=document.querySelector("#measured-"+id+"-state"),root=document.querySelector("#measured-"+id+"-findings");state.textContent=verified?layer.status.replaceAll("_"," "):"unverified";state.className="metric "+(layer.status==="pass"?"verification-ok":layer.status==="fail"?"verification-fail":"verification-warn");if(!verified){root.className="layer-findings";root.textContent="Bundle verification failed.";}else if(!layer.finding_codes.length){root.className="layer-findings layer-clear";root.textContent=layer.status==="not_evaluated"?"No baseline safety invariants were declared.":"No findings in this layer.";}else{root.className="layer-findings";root.replaceChildren(...layer.finding_codes.map(chip));}}}
function renderMeasuredContract(contract,verified){const root=document.querySelector("#measured-contract-summary");if(!verified){root.replaceChildren(definitionFact("Tool","Unverified"),definitionFact("Contract","Not accepted"),definitionFact("Effects","—"),definitionFact("Baseline","—"));return;}const hash=contract.hash?contract.hash.slice(0,18)+"…":"Not available";root.replaceChildren(definitionFact("Tool",contract.tool_name),definitionFact("Contract","v"+contract.version+" · "+hash),definitionFact("Effects",contract.effect_count+" · "+contract.effect_kinds.join(", ")),definitionFact("Baseline",contract.baseline_status.replaceAll("_"," ")+" · "+contract.invariant_count+" invariants"));}
function renderMeasuredGaps(gaps,verified){const root=document.querySelector("#measured-capture-gaps");if(!verified){root.className="empty-state compact-empty";root.textContent="Verification failed. Capture claims are not trusted.";return;}if(!gaps.length){root.className="pass-state compact-empty";root.textContent="No capture gaps in the semantically consistent coverage and assurance record.";return;}root.className="gap-list";root.replaceChildren(...gaps.map(gap=>chip(gap.replaceAll("_"," "))));}
function renderMeasuredTimeline(rows,verified){for(const route of ["human","agent"]){const root=document.querySelector("#measured-"+route+"-timeline");if(!verified){root.className="timeline-list empty";root.textContent="Events hidden because bundle verification failed.";continue;}if(!rows.length){root.className="timeline-list empty";root.textContent="No route events were captured.";continue;}root.className="timeline-list";root.replaceChildren(...rows.map(row=>measuredEventCard(row[route],row)));}}
function measuredEventCard(event,row){const card=document.createElement("div");card.className="timeline-event "+(event?"":"timeline-missing");const head=document.createElement("div");head.className="timeline-event-head";const sequence=document.createElement("span");sequence.className="event-sequence";sequence.textContent=event?"#"+event.sequence:"Not captured";const kind=document.createElement("strong");kind.textContent=row.kind.replaceAll("_"," ");head.append(sequence,kind);if(event){const badge=document.createElement("span");badge.className="source-badge "+(event.trusted_source?"trusted":"asserted");badge.textContent=event.provenance==="recorder_observed"?"Recorder channel":event.provenance==="server_attested"?"Server channel":event.provenance==="page_asserted"?"Page assertion":"Unknown source";head.append(badge);}const value=document.createElement("code");value.className="timeline-value";value.textContent=event?JSON.stringify(event.value):"No matching event";card.append(head,value);if(row.value_changed){const changed=document.createElement("span");changed.className="change-flag";changed.textContent="Route difference";card.append(changed);}return card;}
function renderMeasuredDifferences(differences,findings,verified){document.querySelector("#measured-finding-count").textContent=findings.length+(findings.length===1?" finding":" findings");const root=document.querySelector("#measured-differences");if(!verified){root.className="empty-state";root.textContent="No route differences are shown for a semantically invalid bundle.";return;}if(!differences.length){root.className="pass-state";root.textContent="No synchronized route value differences were observed.";return;}root.className="difference-list";root.replaceChildren(...differences.map(difference=>{const card=document.createElement("article");card.className="difference-card";const head=document.createElement("div");head.className="difference-card-head";const title=document.createElement("strong");title.textContent=difference.kind.replaceAll("_"," ");const codes=document.createElement("div");codes.className="difference-codes";codes.replaceChildren(...(difference.finding_codes.length?difference.finding_codes:["observed_value_difference"]).map(chip));head.append(title,codes);const values=document.createElement("div");values.className="difference-values";values.append(routeValue("Human",difference.human?.value),routeValue("Agent",difference.agent?.value));card.append(head,values);return card;}));}
function routeValue(label,value){const node=document.createElement("div"),name=document.createElement("span"),code=document.createElement("code");name.textContent=label;code.textContent=value===undefined?"Not captured":JSON.stringify(value);node.append(name,code);return node;}
function definitionFact(label,value){const node=document.createElement("div"),term=document.createElement("dt"),description=document.createElement("dd");term.textContent=label;description.textContent=value||"—";node.append(term,description);return node;}
function renderProof(attestation,verified){document.querySelector("#attestation-state").textContent=verified?"Signature valid":"Unverified";document.querySelector("#proof-algorithm").textContent=attestation.proof.algorithm+" · "+attestation.proof.key_id.slice(-12);document.querySelector("#proof-audit").textContent=attestation.audit_id;document.querySelector("#proof-trace").textContent=attestation.effect_trace_hash.slice(0,18)+"…";document.querySelector("#proof-previous").textContent=attestation.previous_attestation_hash?attestation.previous_attestation_hash.slice(0,18)+"…":"Genesis proof";}
async function verifyCurrentAttestation(){if(!app.currentRun)throw new Error("Run an audit first");const result=await api("/api/proof/verify",{attestation:app.currentRun.attestation});document.querySelector("#attestation-state").textContent=result.valid?"Signature valid":"Signature invalid";toast(result.valid?"Ed25519 signature verified":"Attestation verification failed");return result;}
async function approveCurrentContract(){if(!app.currentRun)throw new Error("Run an audit first");const result=await api("/api/contracts/approve",{principalId:app.principalId,contract:app.currentRun.contract},app.authorizationToken);app.currentRun.contract=result.contract;app.currentRun.report.contract=result.contract;document.querySelector("#contract-status").textContent="approved · "+result.contract.approved_by;document.querySelector("#approve-contract-button").disabled=true;toast("Effect contract approved and signed");return result;}
async function buildCurrentCiArtifacts(){if(!app.currentRun)throw new Error("Run an audit first");app.ciArtifacts=await api("/api/ci/artifacts",{reports:[app.currentRun.report]});return app.ciArtifacts;}
async function exportArtifact(format){const artifacts=app.ciArtifacts||await buildCurrentCiArtifacts();const content=format==="junit"?artifacts.junit:JSON.stringify(format==="sarif"?artifacts.sarif:artifacts.json,null,2);download("arena-boundary-audit."+(format==="junit"?"xml":"json"),content,format==="junit"?"application/xml":"application/json");toast(format.toUpperCase()+" exported");}
async function issuePassport(event){event.preventDefault();const data=new FormData(event.currentTarget);app.principalId=String(data.get("principalId"));app.agentId=String(data.get("agentId"));app.authorizationToken=String(data.get("humanAuthorizationToken")||"");const result=await api("/api/passports",{principalId:app.principalId,agentId:app.agentId,scopes:["flights:read","flights:book","browser:execute"],maxAmount:Number(data.get("maxAmount")),ttlSeconds:Number(data.get("minutes"))*60},app.authorizationToken);app.passport=result.token;document.querySelector("#passport-summary").textContent=result.delegation.agent_id+" · 3 scopes · expires "+new Date(result.delegation.expires_at).toLocaleTimeString();document.querySelector("#revoke-button").disabled=false;toast("Scoped delegation issued");}
async function revokePassport(){if(!app.passport)return;const result=await api("/api/delegations/revoke",{passport:app.passport,principalId:app.principalId,reason:"user_revoked"},app.authorizationToken);app.passport=null;document.querySelector("#passport-summary").textContent="Delegation "+result.status+". Replays are denied.";document.querySelector("#revoke-button").disabled=true;toast("Delegation revoked");}
async function runAgentProfileExample(){const result=await api("/api/agents/compare",{baseline:[{agent:{provider:"fixture",model:"agent-alpha",version:"1",harness:"webmcp"},trials:10,completed:9,refused:1,unauthorized_attempts:0,approval_requests:2,injection_follows:0}],current:[{agent:{provider:"fixture",model:"agent-alpha",version:"2",harness:"webmcp"},trials:10,completed:10,refused:0,unauthorized_attempts:3,approval_requests:1,injection_follows:2,arena_denials:3}]});const profile=result.profiles[0];document.querySelector("#agent-profile-result").textContent="Completion +"+Math.round(profile.capability_delta*100)+"% · unauthorized attempts +"+Math.round(profile.unauthorized_attempt_delta*100)+"% · boundary "+profile.boundary_outcome+".";}
function renderScenarioGrid(){document.querySelector("#scenario-grid").replaceChildren(...app.scenarios.map((scenario,index)=>{const button=document.createElement("button");button.className="scenario-card";button.dataset.id=scenario.id;const number=document.createElement("span");number.textContent=String(index+1).padStart(2,"0");const title=document.createElement("strong");title.textContent=scenario.title;const category=document.createElement("small");category.textContent=scenario.category.replaceAll("_"," ");button.append(number,title,category);button.addEventListener("click",()=>selectScenario(scenario.id));return button;}));}
async function loadStatus(){const status=await getJson("/api/status");setStatus("runtime-status",status.persistence==="sqlite_wal_full_sync"?"SQLite WAL":"Memory demo","ok");const proof=await getJson("/.well-known/arena-proof.json");setStatus("proof-status",proof.algorithm+" · "+proof.key_id.slice(-8),"ok");}
function scheduleToolRefresh(){setTimeout(()=>refreshWebMcpTools().catch(showError),0);}function setBusy(value){const button=document.querySelector("#run-button");button.disabled=value;button.textContent=value?"Replaying fixture…":"Run Synthetic Fixture";}function setStatus(id,text,tone){const node=document.querySelector("#"+id);node.textContent=text;node.className="status "+(tone||"");}function chip(value){const node=document.createElement("span");node.textContent=value;return node;}function fact(label,value){const node=document.createElement("p"),strong=document.createElement("strong"),span=document.createElement("span");strong.textContent=label;span.textContent=value||"—";node.append(strong,span);return node;}function display(value){return value===null?"null":typeof value==="string"?value:JSON.stringify(value);}function safePath(value){try{const url=new URL(value);return url.host+url.pathname;}catch{return String(value);}}function download(name,content,type){const blob=new Blob([content],{type}),link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=name;link.click();URL.revokeObjectURL(link.href);}function toast(message){const node=document.querySelector("#toast");node.textContent=message;node.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove("show"),2600);}function showError(error){toast(error.message||String(error));}
async function getJson(path){const response=await fetch(path,{headers:{accept:"application/json"}}),result=await response.json();if(!response.ok)throw new Error(result.error||"Request failed");return result;}async function api(path,body,token){const response=await fetch(path,{method:"POST",headers:{"content-type":"application/json",accept:"application/json",...(token?{authorization:"Bearer "+token}:{})},body:JSON.stringify(body)}),result=await response.json();if(!response.ok)throw new Error(result.error||"Request failed ("+response.status+")");return result;}
document.querySelector("#run-button").addEventListener("click",()=>runScenario().catch(showError));document.querySelector("#fixed-button").addEventListener("click",()=>runScenario("fixed").catch(showError));document.querySelector("#verify-button").addEventListener("click",()=>verifyCurrentAttestation().catch(showError));document.querySelector("#approve-contract-button").addEventListener("click",()=>approveCurrentContract().catch(showError));document.querySelector("#checkout-vulnerable-button").addEventListener("click",()=>startMeasuredCheckoutAudit("vulnerable").catch(showError));document.querySelector("#checkout-fixed-button").addEventListener("click",()=>startMeasuredCheckoutAudit("fixed").catch(showError));document.querySelector("#guided-approve-button").addEventListener("click",()=>approveMeasuredCheckoutAudit().catch(showError));document.querySelector("#measured-verify-button").addEventListener("click",()=>inspectPastedBoundaryBundle().catch(showError));document.querySelector("#scenario-select").addEventListener("change",event=>selectScenario(event.target.value));document.querySelector("#passport-form").addEventListener("submit",event=>issuePassport(event).catch(showError));document.querySelector("#revoke-button").addEventListener("click",()=>revokePassport().catch(showError));document.querySelector("#agent-profile-button").addEventListener("click",()=>runAgentProfileExample().catch(showError));document.querySelectorAll("[data-export]").forEach(button=>button.addEventListener("click",()=>exportArtifact(button.dataset.export).catch(showError)));Promise.all([loadScenarios(),loadStatus()]).then(refreshWebMcpTools).catch(showError);
`;

